/***************************************************************************************************** 
 *
 * 
 * Given a non-empty string s, you may delete at most one character.  Judge whether you can make it a 
 * palindrome.
 * 
 * Example 1:
 * 
 * Input: "aba"
 * Output: True
 * 
 * Example 2:
 * 
 * Input: "abca"
 * Output: True
 * Explanation: You could delete the character 'c'.
 * 
 * Note:
 * 
 * The string will only contain lowercase characters a-z.
 * The maximum length of the string is 50000.
 * 
 ******************************************************************************************************/

class Solution {
    public boolean validPalindrome(String s) {
        var ss = s.toCharArray();
        var start = 0;
        var end = ss.length - 1;
        while (start < end) {
            if (ss[start] != ss[end]) {
                return isPalindrome(ss, start + 1, end) || isPalindrome(ss, start, end - 1);
            }
            start++;
            end--;
        }

        return true;
    }

    boolean isPalindrome(char[] ss, int start, int end) {
        while (start < end) {
            if (ss[start] != ss[end]) {
                return false;
            }
            start++;
            end--;
        }

        return true;
    }
}

package leetcode_solutions_golang

//https://leetcode.com/problems/valid-palindrome-ii/
func validPalindrome(s string) bool {
	left := 0
	right := len(s) - 1
	counter := 0
	for left <= right {
		if counter > 1 {
			break
		}
		if s[left] != s[right] {
			counter++
			right--
		} else {
			left++
			right--
		}
	}
	if counter < 2 {
		return true
	}
	left = 0
	right = len(s) - 1
	counter = 0
	for left <= right {
		if counter > 1 {
			return false
		}
		if s[left] != s[right] {
			counter++
			left++
		} else {
			left++
			right--
		}
	}
	return true
}
